// Governing: ADR-0005 (Scrape Item Stats into a Generated, Committed Data File)
// Implements: SPEC-0007 REQ "Generated, Committed Stats File"
//
// The item-stats seam, mirroring what `hunters.js` is for the roster.
//
// `itemStats.json` is GENERATED by `node scripts/scrape-stats.mjs` and committed — never
// hand-edited. Re-running the scrape rewrites it in place. Everything downstream reads through
// here, so when a stat display lands it needs no knowledge of the file's shape.
//
// The file is `{ _generated: {...}, items: { [catalogId]: record } }`. The wrapper exists because
// JSON carries no comments and SPEC-0007 requires the generated-ness to be visible to whoever
// opens the file; unwrapping it here means no consumer has to know that.
//
// `statsFor` returns null for an unknown id, and that is the specified behaviour rather than a
// gap. SPEC-0007 requires the app to degrade cleanly for an item with no scraped stats — the same
// posture ItemThumb takes when no image exists. The dataset and the catalog refresh independently:
// a newly added catalog row and an item whose page failed to parse are the same state to a
// consumer, and both resolve to null here.

import data from "./itemStats.json";

/** The generated payload's provenance header. */
export const STATS_GENERATED = data._generated ?? null;

/** Every scraped record, keyed by catalog id. */
export const ITEM_STATS = data.items ?? {};

/**
 * The scraped record for a catalog id, or null when there is none.
 *
 * Callers MUST tolerate null rather than assuming coverage — the scrape can fail one item without
 * failing the run, so a partially covered dataset is a normal state, not a broken one.
 */
export function statsFor(id) {
  if (!id) return null;
  return Object.prototype.hasOwnProperty.call(ITEM_STATS, id) ? ITEM_STATS[id] : null;
}

/**
 * Whether the wiki says this weapon can be dual wielded — `true`, `false`, or `null` for not stated.
 *
 * Governing: #178. Added with the scrape's `dualWield` field.
 *
 * THREE-VALUED, and a caller must not collapse it. `true` is read from the page's own words; `false`
 * means a description was read and did not say it, which is an inference from ABSENCE because the wiki
 * asserts dual-wieldability positively and never denies it; `null` means nothing was read.
 *
 * That matters because #178 notes the attribute "feeds the budget math the same way `size` and `cost`
 * do" — a dual-wielded pair costs more slots than one pistol. So `if (dualWieldFor(id))` is safe for
 * offering an affordance, and `if (dualWieldFor(id) === false)` is NOT safe as proof a weapon cannot
 * be paired. Consuming this in the builder is #179, and it needs the catalog schema work first.
 */
export function dualWieldFor(id) {
  const value = statsFor(id)?.dualWield;
  return value === undefined ? null : value;
}

/**
 * The Scarce/Burn rarity classes evidenced for a catalog id, as a SET — never a scalar,
 * because a trait can be both (Death Cheat, Rampage, Relentless and Remedy all carry
 * `Type: "Burn,Scarce"` on the wiki).
 *
 * Governing: ADR-0018 (Surface Acquisition Class as Colour-plus-Text, and Disclose Burn
 * Traits Rather Than Simulate Them), amended 2026-08-16 per #392's Confirmation #1 reader
 * split. Issue #362.
 *
 * TRAIT rows read the scraped `acquisitionClasses` set directly — SPEC-0007 requires
 * every trait record to carry it. NON-TRAIT rows (weapons, tools, consumables) never
 * carry `acquisitionClasses`; that field is scoped to traits by specification, not
 * omitted by accident, so their `scarce` evidence comes from `purchasable === false`
 * instead — the strict scrape parser's own record that `priceStated`/`fields.Price` held
 * the literal string `"Scarce"` rather than a number. This is the same fallback
 * `itemStats.test.js`'s `evidencedUnpurchasable` helper already checks; this function
 * makes it a reusable reader rather than a test-only helper.
 *
 * One function serves both row kinds without being told which kind it was called for:
 * `acquisitionClasses` is always `[]` for a non-trait row, so the `purchasable` fallback
 * can only ever ADD evidence, never contradict a trait's own set — and it does not
 * misfire the other way either: Necromancer is `Burn`, costs 4, and carries
 * `purchasable: true`, so `scarce` correctly stays false for it.
 *
 * Returns `{ scarce, burn }`, both `false` for an unknown id or an item with neither
 * class (e.g. every Regular trait).
 */
export function rarityFor(id) {
  const record = statsFor(id);
  const classes = record?.acquisitionClasses ?? [];
  return {
    scarce: classes.includes("Scarce") || record?.purchasable === false,
    burn: classes.includes("Burn"),
  };
}

/**
 * Short text for a rarity set, in the game's own vocabulary ("Scarce", "Burn"), or null
 * for an item with neither class. This is the TEXT CHANNEL ADR-0018 requires — the
 * badge/cost text a caller substitutes for a hand-authored `0` so it stops reading as an
 * ordinary price. Joined rather than collapsed to one word when a trait is both, per
 * `rarityFor`'s doc comment.
 */
export function rarityLabel(id) {
  const { scarce, burn } = rarityFor(id);
  const parts = [];
  if (scarce) parts.push("Scarce");
  if (burn) parts.push("Burn");
  return parts.length ? parts.join(" · ") : null;
}

/**
 * The spur colours the game itself uses for rarity — blue for Scarce, red for Burn —
 * the OPTIONAL visual half of ADR-0018's colour-plus-text treatment ("Never colour
 * alone", the text channel above is load-bearing on its own). Both are measured against
 * `--panel` (#1a1510), the picker row background, the same way `CONS_TYPE_COLOR` in
 * catalog.js documents its own badge contrast: Scarce blue clears 5.81:1, and Burn reuses
 * `--red-bright`'s hex value (4.95:1) directly, rather than inventing a second red the app
 * doesn't already use elsewhere for a "notable/consumed" meaning. Both clear WCAG 2.1 SC
 * 1.4.3 (4.5:1 for the small badge text they colour).
 */
export const RARITY_COLOR = {
  scarce: "#7a93bd",
  burn: "#c96b5b",
};

/**
 * The scraped description for a catalog id, or null.
 *
 * Governing: ADR-0005 (the "and Descriptions" half of its title), SPEC-0007 REQ "Generated,
 * Committed Stats File". Added with #228.
 *
 * Read through here rather than off the record so callers do not have to know that a description can
 * be absent, or that its paragraphs are newline-joined. Null is a normal outcome: a page can carry a
 * hatnote and no prose, and a catalog row can predate the dataset — those are the same state to a
 * caller, exactly as `statsFor` already documents.
 *
 * The value is UNTRUSTED wiki text. SPEC-0003 states this rule for the hunter descriptions and it
 * applies identically here: render it as text, never as markup. The scrape strips tags, which makes
 * the stored value text rather than a fragment; it does not make it safe to inject.
 */
export function descriptionFor(id) {
  const value = statsFor(id)?.description;
  return value === undefined || value === "" ? null : value;
}

/**
 * One infobox field for a catalog id, or null.
 *
 * Values are the wiki's own strings ("75", "Compact"), deliberately not coerced to numbers here:
 * ADR-0005 gates numeric write-through behind range assertions in the scrape, and a silent
 * `Number()` at the read end would reintroduce exactly the unvalidated coercion those assertions
 * exist to prevent.
 */
export function statFieldFor(id, field) {
  const record = statsFor(id);
  if (!record?.fields) return null;
  const value = record.fields[field];
  return value === undefined || value === "" ? null : value;
}

/**
 * A weapon's ammo slots, derived from its own scraped `ammo` record — never from the
 * shared `AMMO[ammoClass]` pools in catalog.js, and never from the weapon's action type.
 *
 * Governing: ADR-0014, SPEC-0010 REQ "A Weapon Declares Which Rounds It Accepts", REQ "A
 * Weapon Declares Its Own Ammo Slot Count", REQ "A Dual-Family Weapon Declares Both
 * Families" (amended by #431), issue #344.
 *
 * Returns `{ count, bound, groups }`:
 *   - `count` is 0 (no ammo section — melee, Flame Rifle, Shredder), 1, or 2.
 *   - `groups` has exactly `count` entries; `groups[k]` is the list of rounds slot `k`
 *     may hold, each `{ id, name, family, iconSlug, scarce, price }` straight from the
 *     scrape.
 *   - `bound` is true only for a dual-family weapon (#431): `groups[0]` and `groups[1]`
 *     are then two DISJOINT subsets of `accepted`, one per family, and a round from the
 *     family bound to the other slot is not offered in this one — REQ "A Dual-Family
 *     Weapon Declares Both Families" is explicit that the whole `accepted` list is the
 *     record of what the weapon can take, not what either individual slot can take.
 *   - `bound` is false for a one-slot weapon and for a split-reserve two-slot weapon
 *     (e.g. Berthier 1892): both slots then share the SAME group, unrestricted between
 *     them, and the two selections may repeat a round (spec's split-reserve scenario).
 *
 * Slot ORDER for a dual-family weapon follows the scrape's own family order in
 * `accepted` — the wiki lists the weapon's primary family's rounds before its secondary
 * family's (drilling: medium rounds, then shotgun), so group 0 is always the family the
 * page itself leads with. This reads no field decided by this app (not `ammoClass`,
 * which #340/#341 already found types the Drilling to the WRONG family); it reads only
 * the order the scraper — which "observes and does not decide" (SPEC-0010 REQ "The
 * Scrape Observes and Does Not Decide") — already recorded.
 *
 * A weapon whose reserve claims `familySplit` but whose accepted rounds don't actually
 * span exactly two families is a data defect, not a decode-time judgment call for this
 * function to make — it degrades to one unbound slot over the whole list rather than
 * guessing which rounds belong to which slot.
 */
export function ammoSlotsFor(id) {
  const ammo = statsFor(id)?.ammo;
  const accepted = ammo?.accepted;
  if (!Array.isArray(accepted) || accepted.length === 0) return { count: 0, bound: false, groups: [] };
  const reserve = ammo.reserve ?? {};
  if (reserve.familySplit) {
    const families = [];
    for (const round of accepted) if (!families.includes(round.family)) families.push(round.family);
    if (families.length === 2) {
      return { count: 2, bound: true, groups: families.map((f) => accepted.filter((r) => r.family === f)) };
    }
    // Data defect (see doc comment) — fall through to the unbound single-list shape.
  }
  if (Number.isInteger(reserve.perSlotOf)) return { count: 2, bound: false, groups: [accepted, accepted] };
  return { count: 1, bound: false, groups: [accepted] };
}

/**
 * The round a weapon's slot names, or null — looked up by stable id within THAT slot's
 * own group (never a global registry), because REQ "Price Belongs to the Weapon-and-
 * Round Pair" makes price a property of the (weapon, round) pair, not the round alone.
 *
 * Governing: ADR-0014, SPEC-0010 REQ "Price Belongs to the Weapon-and-Round Pair", issue #344.
 *
 * Returns null for an empty slot (`ammoId` is null), an out-of-range `slotIndex`, or an
 * id the slot's group does not contain — e.g. a dual-family weapon's OTHER family's id
 * offered against the wrong slot. Never throws.
 */
export function ammoRoundFor(weaponId, slotIndex, ammoId) {
  if (!ammoId) return null;
  const group = ammoSlotsFor(weaponId).groups[slotIndex];
  if (!group) return null;
  return group.find((r) => r.id === ammoId) ?? null;
}
